from pathlib import Path

p = Path('src/main.jsx')
s = p.read_text()
if 'function Fluxo(' in s:
    print('Finance components already present')
    raise SystemExit(0)

components = r'''
function Section({title,children,action}){return <section className="card"><div className="section-title"><h2>{title}</h2>{action}</div>{children}</section>}
function Row({label,value,onChange,auto=false,action}){return <div className="row"><span>{label}{auto&&<em> automático</em>}</span><input type="number" value={Number(value||0)} onChange={e=>onChange?.(Number(e.target.value)||0)} disabled={auto}/>{action}</div>}
function Kpi({t,v,kind}){return <div className="kpi"><span>{t}</span><strong>{kind==='count'?Number(v||0):t.toLowerCase().includes('compromet')?`${Number(v||0).toFixed(1)}%`:BRL(v)}</strong></div>}
function MonthSelect({month,setMonth,months=MONTHS}){const all=[...new Set(months.concat(month))].filter(Boolean).sort();return <label>Mês de referência<select value={month} onChange={e=>setMonth(e.target.value)}>{all.map(m=><option key={m}>{m}</option>)}</select></label>}
function Fluxo({data,month,setMonth,updateFlux,addSeries,updateSeries,stopSeries}){const f=data.fluxo.find(x=>x.month===month)||{},extras=data.entradas.filter(x=>x.month===month&&x.ativo!==false),custom=data.despesas.filter(x=>x.month===month&&x.ativo!==false),fm=calcFluxoMonth(f,data.prestadores.filter(p=>p.month===month&&p.ativo!==false),custom,extras);return <><div className="toolbar"><MonthSelect month={month} setMonth={setMonth} months={data.fluxo.map(x=>x.month)}/></div><div className="kpis"><Kpi t="Entradas" v={fm.entries}/><Kpi t="Despesas" v={fm.expenses}/><Kpi t="Saldo" v={fm.balance}/></div><div className="grid2"><Section title="Entradas"><Row label="Salário" value={f.salario} onChange={v=>updateFlux({salario:v})}/><Row label="VA" value={f.va} onChange={v=>updateFlux({va:v})}/>{extras.map(x=><Row key={x.id} label={x.nome} value={x.valor} onChange={v=>updateSeries('entradas',x.id,{valor:v})} action={<button className="ghost" onClick={()=>stopSeries('entradas',x.series_id||x.id)}>Encerrar</button>}/>)}<button className="secondary" onClick={()=>{const n=prompt('Nome da nova entrada');if(n){const v=prompt('Valor mensal');if(v!==null)addSeries('entradas',n,v)}}}>+ Nova entrada</button><div className="total">Total <b>{BRL(fm.entries)}</b></div></Section><Section title="Despesas"><div className="note">Prestadores e imposto entram automaticamente. Encerrar preserva o histórico.</div>{FLUXO_FIELDS.map(([k,l])=><Row key={k} label={l} value={f[k]} onChange={v=>updateFlux({[k]:v})}/>)}{custom.map(x=><Row key={x.id} label={x.nome} value={x.valor} onChange={v=>updateSeries('despesas',x.id,{valor:v})} action={<button className="ghost" onClick={()=>stopSeries('despesas',x.series_id||x.id)}>Encerrar</button>}/>)}<Row label="Prestadores de Serviço" value={fm.employeeTotal} auto/><Row label="Imposto" value={fm.tax} auto/><button className="secondary" onClick={()=>{const n=prompt('Nome da nova despesa');if(n){const v=prompt('Valor mensal');if(v!==null)addSeries('despesas',n,v)}}}>+ Nova conta</button></Section></div></>}
function Prestadores({data,save,month,setMonth}){const rows=data.prestadores.filter(x=>x.month===month&&x.ativo!==false),total=rows.reduce((s,x)=>s+totalPrestador(x),0);const add=()=>{const nome=prompt('Nome do prestador');if(!nome)return;const id=crypto.randomUUID();const next=[...data.prestadores,...planningMonths(month,12).map(m=>({id:crypto.randomUUID(),prestador_id:id,month:m,nome,salario:1400,dias_uteis:22,passagem_scs:0,passagem_sp:0,ativo:true}))];save({...data,prestadores:next})};const update=(id,p)=>save({...data,prestadores:data.prestadores.map(x=>x.id===id?{...x,...p}:x)});return <><div className="toolbar"><MonthSelect month={month} setMonth={setMonth} months={data.prestadores.map(x=>x.month)}/><button className="primary" onClick={add}>+ Prestador</button></div><Section title="Prestadores"><div className="kpis"><Kpi t="Custo mensal" v={total}/><Kpi t="Quantidade" v={rows.length} kind="count"/></div>{rows.map(p=><div className="card" key={p.id}><Row label={p.nome||'Prestador'} value={p.salario} onChange={v=>update(p.id,{salario:v})}/><Row label="Dias úteis" value={p.dias_uteis} onChange={v=>update(p.id,{dias_uteis:v})}/><Row label="Passagem SCS" value={p.passagem_scs} onChange={v=>update(p.id,{passagem_scs:v})}/><Row label="Passagem SP" value={p.passagem_sp} onChange={v=>update(p.id,{passagem_sp:v})}/><div className="total">Custo calculado <b>{BRL(totalPrestador(p))}</b></div></div>)}{!rows.length&&<div className="empty">Nenhum prestador neste mês.</div>}</Section></>}
function Transferencias({data,save,month,setMonth}){const rows=data.transferencias.filter(x=>x.month===month&&x.ativo!==false);const add=()=>{const nome=prompt('Descrição da transferência');if(!nome)return;const v=Number((prompt('Valor')||'0').replace(',','.'));if(!v)return;const id=crypto.randomUUID();save({...data,transferencias:[...data.transferencias,{id,series_id:id,month,nome,valor:Math.abs(v),ativo:true}]})};const remove=id=>save({...data,transferencias:data.transferencias.map(x=>x.id===id?{...x,ativo:false}:x)});return <><div className="toolbar"><MonthSelect month={month} setMonth={setMonth} months={data.transferencias.map(x=>x.month)}/><button className="primary" onClick={add}>+ Transferência</button></div><Section title="Transferências">{rows.map(t=><div className="row" key={t.id}><span>{t.nome}</span><strong>{BRL(t.valor)}</strong><button className="ghost" onClick={()=>remove(t.id)}>Encerrar</button></div>)}{!rows.length&&<div className="empty">Nenhuma transferência neste mês.</div>}</Section></>}
function Budget({data,save,month,setMonth}){const accounts=data.budgetAccounts.filter(a=>a.month===month&&a.ativo!==false),spent=a=>data.gastos.filter(g=>g.month===month&&g.budget_account_id===a.id).reduce((s,g)=>s+Number(g.valor||0),0);const addAccount=()=>{const nome=prompt('Nome da nova conta');if(!nome?.trim())return;const budget=Number((prompt('Budget mensal')||'0').replace(',','.'));if(!Number.isFinite(budget)||budget<0)return;save({...data,budgetAccounts:[...data.budgetAccounts,{id:crypto.randomUUID(),month,nome:nome.trim(),budget,ativo:true}]})};const addGasto=a=>{const v=Number((prompt(`Valor de ${a.nome}`)||'0').replace(',','.'));if(!v)return;save({...data,gastos:[...data.gastos,{id:crypto.randomUUID(),month,conta:a.legacy_key||a.id,budget_account_id:a.id,valor:Math.abs(v)}]})};const update=(id,budget)=>save({...data,budgetAccounts:data.budgetAccounts.map(a=>a.id===id?{...a,budget}:a)});return <><div className="toolbar"><MonthSelect month={month} setMonth={setMonth} months={data.budgetAccounts.map(x=>x.month)}/><button className="primary" onClick={addAccount}>+ Conta</button></div><Section title="Entradas x Budget"><div className="kpis"><Kpi t="Budget total" v={accounts.reduce((s,a)=>s+Number(a.budget||0),0)}/><Kpi t="Realizado" v={accounts.reduce((s,a)=>s+spent(a),0)}/><Kpi t="Saldo de budget" v={accounts.reduce((s,a)=>s+Number(a.budget||0)-spent(a),0)}/></div>{accounts.map(a=><div className="row" key={a.id}><span>{a.nome}</span><input type="number" value={Number(a.budget||0)} onChange={e=>update(a.id,Number(e.target.value)||0)}/><strong>{BRL(spent(a))}</strong><button className="secondary" onClick={()=>addGasto(a)}>+ Lançamento</button></div>)}</Section></>}
function Dash({data,month,setMonth}){const [view,setView]=useState('fluxo');return <><div className="toolbar"><MonthSelect month={month} setMonth={setMonth} months={data.fluxo.map(x=>x.month)}/><div><button className={view==='fluxo'?'primary':'ghost'} onClick={()=>setView('fluxo')}>Fluxo</button><button className={view==='budget'?'primary':'ghost'} onClick={()=>setView('budget')}>Budget</button></div></div>{view==='fluxo'?<DashFluxo data={data} month={month} setMonth={setMonth}/>:<DashBudget data={data} month={month}/>}</>}
function DashFluxo({data,month,setMonth}){const refMonth=month||currentMonth(),months=planningMonths(refMonth,12),rows=months.map(m=>{const f=data.fluxo.find(x=>x.month===m)||{},prest=data.prestadores.filter(x=>x.month===m&&x.ativo!==false),entradas=data.entradas.filter(x=>x.month===m&&x.ativo!==false),despesas=data.despesas.filter(x=>x.month===m&&x.ativo!==false);return {m,...calcFluxoMonth(f,prest,despesas,entradas)}}),current=rows.find(x=>x.m===refMonth)||rows[0],negative=rows.filter(x=>x.balance<0).length,best=[...rows].sort((a,b)=>b.balance-a.balance)[0],worst=[...rows].sort((a,b)=>a.balance-b.balance)[0],avg=rows.slice(1).reduce((s,x)=>s+x.balance,0)/Math.max(1,rows.length-1);return <div className="dash-content"><div className="kpis"><Kpi t="Entradas do mês" v={current.entries}/><Kpi t="Despesas do mês" v={current.expenses}/><Kpi t="Saldo do mês" v={current.balance}/><Kpi t="Meses negativos" v={negative} kind="count"/></div><div className="grid2"><Section title="Leitura executiva"><div className="insight-grid"><div><span>Saldo médio futuro</span><strong>{BRL(avg)}</strong></div><div><span>Melhor mês</span><strong>{best.m} · {BRL(best.balance)}</strong></div><div><span>Pior mês</span><strong>{worst.m} · {BRL(worst.balance)}</strong></div></div></Section><Section title="Visão mensal"><div className="table-wrap"><table><thead><tr><th>Mês</th><th>Entradas</th><th>Despesas</th><th>Saldo</th></tr></thead><tbody>{rows.map(x=><tr key={x.m}><td>{x.m}</td><td>{BRL(x.entries)}</td><td>{BRL(x.expenses)}</td><td>{BRL(x.balance)}</td></tr>)}</tbody></table></div></Section></div></div>}
function DashBudget({data,month}){const accounts=data.budgetAccounts.filter(a=>a.month===month&&a.ativo!==false),budget=accounts.reduce((s,a)=>s+Number(a.budget||0),0),spent=accounts.reduce((s,a)=>s+data.gastos.filter(g=>g.month===month&&g.budget_account_id===a.id).reduce((x,g)=>x+Number(g.valor||0),0),0);return <Section title={`Budget · ${month}`}><div className="kpis"><Kpi t="Budget" v={budget}/><Kpi t="Realizado" v={spent}/><Kpi t="Disponível" v={budget-spent}/></div></Section>}
'''
marker="\nconst root=document.getElementById('root')"
if marker not in s:
    raise SystemExit('React root marker not found')
s=s.replace(marker,'\n'+components+marker,1)
p.write_text(s)
print('Restored missing Finance components before React root')
